{"HelperA.dfy": "    var inner := K.Put(m,p,m[q]);
    var swapped := K.Exchange(m,p,q);
    O.ExchangeShape(m,p,q);
    O.PutKeys(m,p,m[q]);
    assert inner.Keys == m.Keys;
    O.PutKeys(inner,q,m[p]);
    assert swapped.Keys == m.Keys;
    forall x | x in m ensures x in swapped &&
      swapped[x] == (if x == p then m[q] else if x == q then m[p] else m[x]) {
      O.PutAt(m,p,m[q],x);
      O.PutAt(inner,q,m[p],x);
    }
", "HelperB.dfy": "    var u := m[p];
    var v := m[q];
    assert u in n && v in n;
    assert n[u] == p && n[v] == q;
    assert u != v;
    H.Prove(m,p,q);
    H.Prove(n,u,v);
    var forward := K.Exchange(m,p,q);
    var backward := K.Exchange(n,u,v);
    forall x | x in forward ensures forward[x] in backward && backward[forward[x]] == x {
      assert x in m;
      assert n[m[x]] == x;
      if x == p {
        assert forward[x] == v;
        assert backward[v] == p;
      } else if x == q {
        assert forward[x] == u;
        assert backward[u] == q;
      } else {
        assert m[x] != u && m[x] != v;
        assert forward[x] == m[x];
        assert backward[m[x]] == n[m[x]];
      }
    }
    forall y | y in backward ensures backward[y] in forward && forward[backward[y]] == y {
      assert y in n;
      assert m[n[y]] == y;
      if y == u {
        assert backward[y] == q;
        assert forward[q] == u;
      } else if y == v {
        assert backward[y] == p;
        assert forward[p] == v;
      } else {
        assert n[y] != p && n[y] != q;
        assert backward[y] == n[y];
        assert forward[n[y]] == m[n[y]];
      }
    }
"}
